mapper.select:
SELECT id, domain, document, category, author_source, keywords, context_trigger, last_modified_at
FROM cms.wisdoms
WHERE id = #{id}

SELECT DISTINCT category FROM cms.wisdoms
domain = #{domain}
ORDER BY category

SELECT count(*)
FROM cms.wisdoms
WHERE id = #{id}

SELECT id, domain, document, category, author_source, keywords, context_trigger, last_modified_at FROM cms.wisdoms
AND domain = #{domain}
AND category = #{category}
AND context_trigger ILIKE CONCAT('%', #{contextTrigger}, '%')
ORDER BY RANDOM() LIMIT 1
